// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: mbrola:tr1
window.VOICE = {"engine":"mbrola:tr1","gain":1.25,"lines":[{"id":"open-title","say":"Birinci kapı. Var ve yok: iki simgeli bir evren.","at":3.8,"dur":4.082,"marks":[0,1.491,2.687]},{"id":"fires-one","say":"Dağın tepesinde bir ateş yanıyor.","at":9.582,"dur":2.018,"marks":[0]},{"id":"fires-meaning","say":"Ne anlama geldiği önceden kararlaştırılmıştı: düşman sınırı geçti.","at":12.05,"dur":4.628,"marks":[0,3.173]},{"id":"fires-relay","say":"Karşı tepedeki nöbetçi, ateşi görür görmez kendi ateşini yakardı; ondan ötekisi, ondan berikisi.","at":18.378,"dur":7.387,"marks":[0,1.965,4.972,6.305]},{"id":"fires-race","say":"Böylece haber, atlının günlerce süren yolculuğunu saatlere indirirdi.","at":26.865,"dur":4.411,"marks":[0,1.286]},{"id":"fires-question","say":"Peki, ateş tam olarak ne söylüyordu?","at":32.776,"dur":2.652,"marks":[0,0.798]},{"id":"fires-answer","say":"Aslında tek bir şey: oldu.","at":36.428,"dur":2.187,"marks":[0,1.774]},{"id":"two-split","say":"Yanıyorsa oldu, yanmazsa olmadı. İki durum: var ve yok.","at":40.815,"dur":4.883,"marks":[0,1.349,2.998,4.137]},{"id":"two-levels","say":"Peki ateşle elli ayrı haber verilseydi? Biraz yanarsa asker, yarı yanarsa gemi, gürül gürül yanarsa savaş.","at":46.698,"dur":7.815,"marks":[0,3.022,4.689,6.184]},{"id":"two-weather","say":"Şimdi bir de yağmur yağsın, sis çöksün. Yorgun bir nöbetçi, ateşin biraz mı, yarı mı yandığını kestiremez. Ama yanıyor mu, yanmıyor mu; bunu her zaman görür.","at":55.513,"dur":12.599,"marks":[0,2.05,3.596,5.258,6.647,8.906,10.116,11.307]},{"id":"two-quote","say":"İki durum arasında yanılmak, elli durum arasında yanılmaktan çok daha güçtür.","at":69.512,"dur":5.066,"marks":[0,2.019]},{"id":"two-icons","say":"Bu tek cümle, telefonun, televizyonun, bankadaki hesabın ve bu kitabın temelidir.","at":76.678,"dur":6.139,"marks":[0,1.21,2.282,3.502]},{"id":"why-volt","say":"Bugünün makineleri de ateş yerine elektrik kullanır. Bir teldeki elektriğin ne kadar güçlü ittiğini, volt denen birimle ölçeriz.","at":84.717,"dur":8.617,"marks":[0,3.743,6.946]},{"id":"why-wobble","say":"Ama bu değer hiç yerinde durmaz: sıcaklık değişir, kablonun direnci artar, komşu devreden parazit gelir. Tam üç virgül yetmiş dört volt dersiniz, bir saniye sonra yanılırsınız.","at":93.784,"dur":12.887,"marks":[0,2.333,3.939,5.733,8.175,11.092]},{"id":"why-threshold","say":"Ama şu soruyu sormak kolay: elektrik var mı, yok mu? Makine ortaya bir çizgi çeker; buna eşik denir. Üstündeyse var, altındaysa yok; değeri biraz oynasa bile, cevap değişmez.","at":107.771,"dur":14.363,"marks":[0,2.184,3.591,4.735,7.11,8.761,10.133,11.547,13.367]},{"id":"why-code","say":"Elektrik var, bir. Elektrik yok, sıfır.","at":122.584,"dur":4.048,"marks":[0,1.297,2.243,3.505]},{"id":"why-bit","say":"Bu iki değerin her birine bit denir. Bit, bilişimin atomudur: bölünemeyen en küçük bilgi parçası.","at":129.232,"dur":7.26,"marks":[0,2.662,3.31,4.973]},{"id":"why-pairs","say":"Tek başına çok az şey anlatır: evet ya da hayır, açık ya da kapalı.","at":136.942,"dur":4.971,"marks":[0,2.407,3.788]},{"id":"lamps-one","say":"Bir lamba kadar: sönükse sıfır, yanıyorsa bir. İki durum. Ama bitleri yan yana dizince, bir şey olur.","at":143.713,"dur":8.639,"marks":[0,1.485,2.912,4.454,5.743,7.782]},{"id":"lamps-two","say":"İki lamba düşünün. Kaç farklı durum kurabilirsiniz? Kapalı kapalı, kapalı açık, açık kapalı, açık açık. Dört.","at":153.252,"dur":10.028,"marks":[0,1.823,4.587,5.878,6.998,8.281,9.632]},{"id":"lamps-three","say":"Üç lamba? Sekiz durum. Çünkü yeni lamba sönükken, eski dört durum aynen kurulur; yanarken, aynı dört durum bir kez daha. Dört artı dört, sekiz.","at":164.18,"dur":12.59,"marks":[0,1.389,2.857,4.952,7.304,8.366,10.79,12.095]},{"id":"lamps-four","say":"Dört lamba? On altı. Her yeni lamba, olasılıkları ikiye katlar.","at":178.27,"dur":5.639,"marks":[0,1.486,2.626,3.96]},{"id":"lamps-table","say":"Katlamayı sürdürün: otuz iki, altmış dört, yüz yirmi sekiz, iki yüz elli altı. Sekiz lamba, iki yüz elli altı durum.","at":184.809,"dur":9.564,"marks":[0,1.664,2.65,3.869,5.237,6.916,8.181]},{"id":"lamps-big","say":"Otuz iki lambada durum sayısı dört milyarı aşar. Sezgimiz en çok burada yanılır.","at":194.823,"dur":5.472,"marks":[0,3.52]},{"id":"lamps-byte","say":"Sekiz bit yan yana gelince, buna bayt denir.","at":201.995,"dur":3.076,"marks":[0,2.061]},{"id":"lamps-values","say":"Her lambanın bir değeri vardır: sağdan sola bir, iki, dört, sekiz, böyle ikiye katlanarak, yüz yirmi sekize kadar. Yanan lambaların değerleri toplanır.","at":206.071,"dur":12.169,"marks":[0,2.323,3.756,4.495,5.243,6.089,7.867,9.953]},{"id":"lamps-range","say":"Hepsi kapalıysa sıfır, hepsi açıksa, iki yüz elli beş. Bir bayt, sıfırla birlikte iki yüz elli altı ayrı sayı tutar.","at":218.69,"dur":8.766,"marks":[0,1.887,3.227,4.873,5.784]},{"id":"lamps-letters","say":"Bu, bir alfabenin bütün harflerine, rakamlara ve işaretlere yeter. Bir bayt, kabaca bir harftir.","at":229.056,"dur":7.666,"marks":[0,0.647,2.986,5.539,6.45]},{"id":"glossary-rows","say":"Kilo, kilogramdaki gibi bin demektir; her basamak bin kat büyür. Kilobayt kısa bir mektup, megabayt bir şarkı, gigabayt bir film, terabayt bir kütüphane.","at":238.522,"dur":12.07,"marks":[0,0.769,3.195,5.496,7.417,9.092,10.61]},{"id":"glossary-compare","say":"Otuz bin harflik bir metin, otuz kilobayttır. Tek bir fotoğraf ise, yüz kat daha fazla yer kaplar.","at":251.592,"dur":7.438,"marks":[0,2.053,3.801,5.494]},{"id":"letters-question","say":"Makine yalnızca sıfır ile bir biliyorsa, ekranda gördüğümüz A harfi nedir?","at":260.73,"dur":4.765,"marks":[0,2.755]},{"id":"letters-answer","say":"Makinenin içinde A harfi diye bir şey yoktur; altmış beş sayısı vardır.","at":267.195,"dur":4.925,"marks":[0,3.2]},{"id":"letters-encoding","say":"İnsanlar anlaştı: her harfe bir numara. Buna karakter kodlaması denir.","at":273.12,"dur":5.472,"marks":[0,1.59,3.537]},{"id":"letters-cards","say":"A harfi altmış beş, be altmış altı, küçük a doksan yedi, boşluk bile otuz iki.","at":279.042,"dur":6.091,"marks":[0,1.637,3,4.709]},{"id":"letters-merhaba","say":"Makinenin belleğinde merhaba yazmaz; şu yazar: yetmiş yedi, altmış dokuz, seksen iki, yetmiş iki, altmış beş, altmış altı, altmış beş.","at":286.133,"dur":12.024,"marks":[0,2.672,3.781,5.026,6.299,7.534,8.757,9.948,11.181]},{"id":"letters-bits","say":"Onlar da lambalardaki gibi, var yok dizileri olarak durur: altmış beş, altmış dört artı bir.","at":298.607,"dur":6.809,"marks":[0,2.012,4.232,5.423]},{"id":"letters-fonts","say":"Harfin şeklini yazı tipi çizer; makine yalnızca numarasını bilir.","at":307.016,"dur":4.52,"marks":[0,2.51]},{"id":"turkish-grid","say":"İlk anlaşmayı İngilizce konuşanlar yaptı. Yirmi altı harflik alfabeleri için, yüz yirmi sekiz yer ayırdılar; içine sığdı, arttı bile.","at":313.236,"dur":10.01,"marks":[0,3.198,5.77,8.059,9.275]},{"id":"turkish-half","say":"Oysa bir bayt iki yüz elli altı yer sunar; öteki yarı boş kaldı.","at":324.196,"dur":4.211,"marks":[0,2.838]},{"id":"turkish-letters","say":"Türkçenin çe, yumuşak ge, noktasız ı, büyük noktalı i, ö, şe, ü; bu yedi harf o listede yoktu.","at":329.357,"dur":8.848,"marks":[0,1.384,2.583,3.745,5.134,5.713,6.429,7.103]},{"id":"turkish-place","say":"Her ülke, boş yarıya kendi harflerini koydu; ama herkes, farklı yere.","at":339.155,"dur":5.68,"marks":[0,1.029,3.674,4.817]},{"id":"turkish-mojibake","say":"Belge gönderince yola harf değil, sayı çıkar. Sizde iki yüz kırk, yumuşak ge harfidir; karşıdaki sözlükte ise bambaşka bir harf.","at":346.435,"dur":9.962,"marks":[0,2.376,3.819,5.407,7.247]},{"id":"turkish-agreement","say":"Kimse art niyetli değildi; yalnızca sözlükler farklıydı.","at":357.397,"dur":4.094,"marks":[0,2.076]},{"id":"turkish-unicode","say":"Çözüm, bütün yazıları tek bir dev listede toplamaktı: Yunikod. Türk harfleri de, Çin yazısı da, emojiler de orada.","at":362.491,"dur":9.037,"marks":[0,0.897,4.08,5.239,6.717,8.004]},{"id":"turkish-codepoint","say":"Artık yumuşak ge, her yerde aynı numaradır: iki yüz seksen yedi. Bu sayı için tek bayt yetmez; iki bayt gerekir.","at":371.978,"dur":8.853,"marks":[0,1.563,3.5,5.444,7.691]},{"id":"turkish-master","say":"Teknolojideki sorunların çoğu, teknik değil, anlaşma sorunudur. İki taraf aynı sözlüğe bakmıyorsa, kabloların hiçbir suçu yoktur.","at":381.831,"dur":9.874,"marks":[0,2.306,3.531,5.344,7.846]},{"id":"hex-blur","say":"Uzun bit dizilerini okumak göze işkencedir. Bu yüzden bir kısaltma kullanılır: onaltılık düzen.","at":393.605,"dur":6.832,"marks":[0,3.193,5.774]},{"id":"hex-digits","say":"Dört lambanın on altı durumu vardı; her birine tek bir simge gerekir. Rakamlarımız ise on tane, sıfırdan dokuza; kalan altısı için harfler kullanılır: A on, be on bir, böyle sırayla, fe on beşe kadar.","at":401.437,"dur":15.607,"marks":[0,2.519,5.156,7.055,8.664,11.465,12.18,13.18,14.468]},{"id":"hex-split","say":"Diziyi dörderli gruplara bölün. Dört lambanın değerleri sekiz, dört, iki, bir. İlk grupta sekiz, dört ve bir yanıyor: on üç, yani de. İkinci grupta dört ile iki: altı. Kısaca, de altı.","at":418.044,"dur":16.798,"marks":[0,2.485,4.762,5.51,6.249,7.195,8.668,10.356,11.142,12.24,14.351,15.357,16.273]},{"id":"hex-colors","say":"Web sayfalarında renkler böyle yazılır. Ekrandaki her renk, kırmızı, yeşil ve mavi ışığın karışımıdır; koddaki üç çift, bu üç ışığın miktarıdır.","at":436.742,"dur":11.19,"marks":[0,3.04,4.652,5.569,8.216,9.67]},{"id":"hex-red","say":"Fe fe en çok, yani iki yüz elli beş; sıfır sıfır, hiç. Kırmızı sonuna kadar açık, öbürleri kapalı: katıksız kırmızı. Hepsi kapalı siyah, hepsi açık beyaz.","at":448.382,"dur":13.161,"marks":[0,1.197,2.931,4.215,5.201,7.158,8.666,10.453,12.033]},{"id":"hex-phone","say":"Yeni bir bilgi değil, aynı bilginin kolay okunan kılığıdır; tıpkı telefon numarasını bölerek yazmak gibi.","at":463.043,"dur":6.982,"marks":[0,1.551,4.242]},{"id":"numbers-photo","say":"Bir fotoğraf, sık dokunmuş bir kumaş gibidir: yakından bakınca minicik kareler görürsünüz, pikseller.","at":471.725,"dur":7.632,"marks":[0,1.245,3.746,6.854]},{"id":"numbers-pixel","say":"Her pikselin üç sayısı vardır: kırmızının, yeşilin ve mavinin miktarı. Milyonlarca piksel, milyonlarca üçlü sayı.","at":479.807,"dur":9.097,"marks":[0,2.469,3.596,6.017,7.659]},{"id":"numbers-sound","say":"Ses, havadaki basınç dalgasıdır. Saniyede on binlerce kez ölçülür; her ölçüm bir sayıdır. Bu sayılar aynı hızla hoparlöre verilince, kulak aynı sesi yeniden duyar.","at":489.904,"dur":12.445,"marks":[0,0.754,3.23,5.758,7.786,10.594]},{"id":"numbers-video","say":"Videoda ise, her saniyede yirmi beş kadar fotoğraf vardır; göz onları akan bir hareket olarak görür.","at":503.249,"dur":6.816,"marks":[0,1.101,4.379]},{"id":"numbers-sensors","say":"Sıcaklık, nem, mesafe, kalp atışı; bunların hepsi, sensörler sayesinde sayıya dönüşür.","at":511.065,"dur":7.714,"marks":[0,1.033,1.766,2.734,3.994,5.39]},{"id":"numbers-statement","say":"Ortak nokta şudur: ölçülebilen her şey sayıya çevrilebilir; sayıya çevrilen her şey, işlenebilir, saklanabilir, iletilebilir.","at":519.779,"dur":10.029,"marks":[0,1.702,4.712,6.678,7.895,9.196]},{"id":"numbers-danger","say":"Bilişim çağının bütün gücü de, bütün tehlikesi de, bu tek cümlede saklıdır.","at":530.258,"dur":5.364,"marks":[0,2.23,3.817]},{"id":"numbers-watched","say":"Çünkü bu cümle, insan için de geçerlidir: nerede olduğunuz, kiminle konuştuğunuz, neye baktığınız, neyi kaç saniye izlediğiniz.","at":537.422,"dur":9.37,"marks":[0,1.349,3.43,4.713,6.298,7.639]},{"id":"numbers-power","say":"Ölçmek, güçtür.","at":548.292,"dur":1.578,"marks":[0,0.953]},{"id":"numbers-question","say":"Ve her güç gibi, kimin elinde olduğu sorusunu doğurur.","at":550.32,"dur":3.507,"marks":[0,1.419]},{"id":"close-end","say":"Var ve yok.","at":556.027,"dur":0.746,"marks":[0]}],"audio":""};
